#!/usr/bin/env node
// Runs after every build (see package.json's build script) and tells Bing/
// Yandex/Seznam/Naver about every URL on the site via IndexNow —
// https://www.indexnow.org. Google does not support this protocol (confirmed
// as of 2026), so this only accelerates non-Google indexing, but it's free
// and near-instant for the engines that do.
//
// This site's sitemap is generated by @astrojs/sitemap, which always writes
// a sitemap-index.xml plus one or more numbered shards (sitemap-0.xml, ...)
// — unlike personal-site's hand-rolled flat sitemap.xml, so this script
// reads the index first, then every shard it points to.

import { readFileSync } from 'node:fs';
import { join } from 'node:path';

const KEY = 'a60df9d7b779d94015dc72711784814e';
const HOST = 'mlsystems.dev';
const DIST = join(process.cwd(), 'dist');

function locsIn(xml) {
  return [...xml.matchAll(/<loc>(.*?)<\/loc>/g)].map((m) => m[1]);
}

let indexXml;
try {
  indexXml = readFileSync(join(DIST, 'sitemap-index.xml'), 'utf8');
} catch {
  console.warn('[indexnow] No sitemap-index.xml — skipping ping.');
  process.exit(0);
}

const shardUrls = locsIn(indexXml);
const urlList = shardUrls.flatMap((shardUrl) => {
  const filename = new URL(shardUrl).pathname.split('/').pop();
  try {
    return locsIn(readFileSync(join(DIST, filename), 'utf8'));
  } catch {
    console.warn(`[indexnow] Could not read shard ${filename} — skipping it.`);
    return [];
  }
});

if (urlList.length === 0) {
  console.warn('[indexnow] No URLs found across sitemap shards — skipping ping.');
  process.exit(0);
}

try {
  const res = await fetch('https://api.indexnow.org/indexnow', {
    method: 'POST',
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
    body: JSON.stringify({
      host: HOST,
      key: KEY,
      keyLocation: `https://${HOST}/${KEY}.txt`,
      urlList,
    }),
  });
  // IndexNow returns 200/202 on success; it does not echo per-URL results.
  console.log(`[indexnow] Submitted ${urlList.length} URLs — status ${res.status}`);
} catch (err) {
  // Never fail the build over a best-effort notification.
  console.warn(
    `[indexnow] Ping failed, continuing anyway: ${err instanceof Error ? err.message : err}`,
  );
}
